import yaml, json, subprocess, os

def render_kanban(project):
    path = project["path"]
    tasks_json = subprocess.run(["task-master", "list", "--json"], cwd=path, capture_output=True, text=True, check=True).stdout
    tasks = json.loads(tasks_json)

    # Categorize: needs-attention, in-progress, done-today, backlog, fixes
    categories = {"needs-attention": [], "in-progress": [], "done-today": [], "backlog": [], "fixes": []}
    for t in tasks:
        if t.get("status") == "blocked" or t.get("priority") == "high" and t.get("status") == "pending":
            categories["needs-attention"].append(t)
        elif t.get("status") == "in-progress":
            categories["in-progress"].append(t)
        elif t.get("status") == "done" and is_today(t.get("completed_at")):
            categories["done-today"].append(t)
        elif t.get("type") == "fix":
            categories["fixes"].append(t)
        else:
            categories["backlog"].append(t)

    with open(f"{path}/kanban_board.md", "w") as kb:
        kb.write(f"# {project['name']} Kanban\n\n")
        for cat, tasks in categories.items():
            kb.write(f"## {cat.replace('-', ' ').title()} ({len(tasks)})\n")
            for t in tasks:
                kb.write(f"- **T-{t['id']}** {t['title']} [{t.get('status', 'pending')}]\n")
            kb.write("\n")

def is_today(timestamp):
    import datetime
    if not timestamp: return False
    return datetime.date.fromisoformat(timestamp[:10]) == datetime.date.today()

def main():
    with open("~/.kira-hq/projects.yaml") as f:
        projects = yaml.safe_load(f)["projects"]
    for p in [p for p in projects if p["status"] == "active"]:
        render_kanban(p)
