from fastapi import Query

@router.get("/{name}/tasks")
def get_project_tasks(name: str, status: str = Query(None), priority: str = Query(None)):
    with open(Path.home() / ".kira-hq" / "projects.yaml") as f:
        projects = yaml.safe_load(f)["projects"]
    project = next((p for p in projects if p["name"] == name), None)
    if not project:
        raise HTTPException(404, "Project not found")

    tasks_json = subprocess.run(
        ["task-master", "list", "--json"],
        cwd=project["path"], capture_output=True, text=True
    ).stdout
    tasks = json.loads(tasks_json) if tasks_json else []

    # Filter
    if status:
        tasks = [t for t in tasks if t.get("status") == status]
    if priority:
        tasks = [t for t in tasks if t.get("priority") == priority]

    return {"project": name, "tasks": tasks}
