from fastapi import APIRouter, Query
import json, glob
from pathlib import Path
from datetime import datetime, timedelta

router = APIRouter(prefix="/metrics", tags=["metrics"])

@router.get("/tokens")
def tokens(since: str = Query(None), until: str = Query(None)):
    metrics_dir = Path.home() / ".kira-hq" / "metrics"
    files = sorted(glob.glob(str(metrics_dir / "tokens-*.json")))

    # Filter by date range if provided
    if since:
        files = [f for f in files if f.split("-")[-1].replace(".json", "") >= since]
    if until:
        files = [f for f in files if f.split("-")[-1].replace(".json", "") <= until]

    totals = {}
    for fpath in files:
        with open(fpath) as f:
            daily = json.load(f)
            for proj, counts in daily.items():
                if proj not in totals:
                    totals[proj] = {"in": 0, "out": 0}
                totals[proj]["in"] += counts["in"]
                totals[proj]["out"] += counts["out"]

    return {"totals": totals, "period": {"since": since, "until": until}}
